 */
public record RecalledAncestorResponse(
        String batchKey,
        String reason,
        Instant recalledAt
) {
}

package com.example.starter.batch.dto;

import java.util.List;

/**
 * 血缘查询中的单个批次节点：批次自身概要（含自身状态）及导致其不可用的召回祖先列表（无则为空）。
 */
public record LineageNodeResponse(
        BatchResponse batch,
        List<RecalledAncestorResponse> recalledAncestors
) {
}

package com.example.starter.batch.dto;

import java.util.List;

/**
 * 祖先/后代查询响应：self 为被查询批次节点；
 * ancestors 由近及远（直接父批在前，根祖先在后）；descendants 按层次（BFS）排列。
 */
public record LineageResponse(
        LineageNodeResponse self,
        List<LineageNodeResponse> ancestors,
        List<LineageNodeResponse> descendants
) {
}

